import{_ as d,C as r,o as a,c as o,E as n,a4 as i}from"./chunks/framework.BMj-uaUw.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"从这一周开始，所有练习都在同一个项目里做","slug":"从这一周开始-所有练习都在同一个项目里做","link":"#从这一周开始-所有练习都在同一个项目里做","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"术语约定","slug":"术语约定","link":"#术语约定","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit09/index.md","filePath":"unit09/index.md","lastUpdated":1789356894000}'),l={name:"unit09/index.md"};function s(c,t,h,u,g,p){const e=r("UnitMeta");return a(),o("div",null,[n(e,{unit:"单元 9",title:"路由 Vue Router 与登录鉴权",module:"模块四 · 应用架构",hours:"4 学时",week:"第 9 周",goals:["能设计合理的路由结构组织多页面应用","能实现带权限校验的访问控制","能配置路由懒加载"],outcomes:["带鉴权的页面骨架"]}),t[0]||(t[0]=i('<h2 id="从这一周开始-所有练习都在同一个项目里做" tabindex="-1">从这一周开始，所有练习都在同一个项目里做 <a class="header-anchor" href="#从这一周开始-所有练习都在同一个项目里做" aria-label="Permalink to &quot;从这一周开始，所有练习都在同一个项目里做&quot;">​</a></h2><p>前八周的练习，每个页面基本都是<strong>独立的小实验</strong>：这一周写个计数器，下一周写个列表， 写完就放在一边。从第 9 周开始，规则变了。</p><p><strong>第 9 周起，所有练习都要写进同一个项目仓库 —— 校园活动服务平台管理端。</strong> 前八周写的东西会被一个个接进来：列表页、表单页、组件、组合式函数， 都要在同一个应用里跑起来。</p><p>这意味着你要第一次面对“<strong>一个应用有很多页面</strong>”这件事：</p><ul><li>地址栏输入 <code>/activities/12</code>，怎么知道该显示哪份活动详情？</li><li>没登录的用户访问 <code>/activities</code>，怎么把他挡回登录页？</li><li>审核员访问 <code>/dashboard</code>（数据看板），怎么告诉他“你没有权限”，而不是白屏？</li><li>十几个页面全打进一个文件，首屏要等好几秒，怎么办？</li></ul><p>这四个问题的答案都在这一周：<strong>路由</strong>。</p><div class="tip custom-block"><p class="custom-block-title">这一周的分量</p><p>路由是“从单页练习到完整应用”的那道门。学完这一周，你就有能力把前八周的所有页面 组织成一个能点、能跳转、有登录的应用 —— 也就是课程要求的“带鉴权的页面骨架”。</p><p><strong>这个骨架是第 10 到 12 周的基础</strong>：单元 10 往里加数据请求，单元 11 填核心业务， 单元 12 联调上线。骨架搭不好，后面每一步都会被牵制。</p></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit09/01-router-basics.html">9.1 路由基础</a></td><td>单页应用为什么需要路由、路由表、<code>RouterView</code> / <code>RouterLink</code>、编程式导航、两种模式</td><td>地址和页面怎么对应起来</td></tr><tr><td><a href="/frontend-engineering-course/unit09/02-nested-params.html">9.2 动态参数与嵌套路由</a></td><td>动态参数、查询参数、<code>useRoute</code>、嵌套路由、重定向、404、懒加载</td><td>多页面应用的目录结构怎么设计</td></tr><tr><td><a href="/frontend-engineering-course/unit09/03-guards.html">9.3 路由守卫</a></td><td>四种守卫、执行顺序、<code>beforeEach</code> 参数与返回值、异步判断</td><td>在跳转前后插入自己的逻辑</td></tr><tr><td><a href="/frontend-engineering-course/unit09/04-auth-flow.html">9.4 登录鉴权完整链路</a></td><td>写凭证、恢复登录态、401 处理、登录后回原页面、退出清理</td><td>把“登录”这件事从头到尾做完</td></tr><tr><td><a href="/frontend-engineering-course/unit09/05-case-auth.html">案例 10 · 登录与鉴权</a></td><td>登录页、状态模块、两级权限、刷新保持、401 自动跳转</td><td>完整实现一套能用的鉴权</td></tr><tr><td><a href="/frontend-engineering-course/unit09/ai-collaboration.html">AI 协作 · 前端判断不是安全边界</a></td><td>守卫能防到什么程度、token 怎么存、退出时清动态路由</td><td>安全结论不能由 AI 下</td></tr></tbody></table><p>前三节是“会用路由”，9.4 和案例 10 是“会用路由做鉴权”，也就是这个单元的核心。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：单页应用里，地址栏变了但页面不刷新，是怎么做到的？</td></tr><tr><td>讲解</td><td>1.5 学时</td><td>重点讲 9.1 的路由表与 9.3 的守卫执行顺序；9.2 以演示为主</td></tr><tr><td>现场任务</td><td>1.7 学时</td><td>搭出管理端的完整路由表 + 一个能拦住未登录用户的守卫</td></tr><tr><td>复盘</td><td>0.5 学时</td><td>对比两份路由表，讨论“嵌套结构怎么分才合理”</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">这次课最容易做错的地方</p><p><strong>刷新页面时“先渲染还是先校验”的时序问题。</strong> 用户刷新页面，token 还在本地存储里， 但用户信息需要异步请求才知道。如果判断逻辑写在渲染之后，会先闪一下“未登录” 再跳到登录页 —— 或者反过来，先渲染了受限页面再被踢出去。</p><p>正确做法是 9.4 讲的 <code>ready</code> 标记：<strong>在应用挂载之前，先把登录态准备好。</strong> 这个坑案例 10 会重点讲，这里先埋个伏笔。</p></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这个单元假设你已经：</p><ul><li>会写 Vue 组件、会用一个前端脚手架创建项目（<a href="/frontend-engineering-course/unit02/04-vite.html">单元 2</a>）。</li><li>知道 <code>ref</code> / <code>computed</code> 的基本用法（<a href="/frontend-engineering-course/unit04/04-reactivity.html">单元 4</a>）。</li><li>用过 <code>provide/inject</code> 或至少理解“跨组件共享状态”这件事（<a href="/frontend-engineering-course/unit08/02-provide-inject.html">单元 8</a>）。</li></ul><p>路由本身不难，难在<strong>把它和登录态、权限、布局组织在一起</strong>。 这也是为什么这个单元放在组件化之后 —— 你得先把组件写好，路由才有东西可以组织。</p><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p><strong>带鉴权的页面骨架</strong></p><p>一个能跑起来的应用骨架，包含：</p><table tabindex="0"><thead><tr><th>部分</th><th>要求</th></tr></thead><tbody><tr><td>路由表</td><td>覆盖登录、布局、活动列表、活动详情、审核、场次、看板、403、404，全部懒加载</td></tr><tr><td>登录页</td><td>表单校验、提交中状态、错误提示</td></tr><tr><td>登录态</td><td>token 与用户信息存在一个状态模块里，刷新后能恢复</td></tr><tr><td>守卫</td><td>未登录访问受限页面会被挡回登录页，并带上原地址</td></tr><tr><td>两级权限</td><td>菜单级（看不到入口）与按钮级（看不到按钮），都从同一份权限数据推导</td></tr><tr><td>退出登录</td><td>清掉该清的，回到登录页</td></tr></tbody></table><details class="details custom-block"><summary>合格与不合格的差别</summary><p><strong>不合格</strong>：每个页面都能直接访问，登录只是个摆设 —— 在地址栏直接输 <code>/activities</code> 照样能进。或者权限判断写了两份，菜单里藏了但路由里没拦， 用户手输地址还能进。</p><p><strong>合格</strong>：无论从菜单点、手输地址还是刷新页面进入，受限页面都会被正确拦住； 菜单、路由、按钮的权限判断来自<strong>同一份数据</strong>，不会出现“菜单看不见但地址能进”的矛盾。</p></details><h2 id="术语约定" tabindex="-1">术语约定 <a class="header-anchor" href="#术语约定" aria-label="Permalink to &quot;术语约定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在这里指什么</th></tr></thead><tbody><tr><td>路由</td><td>地址和页面之间的对应关系；也指管理这套关系的库</td></tr><tr><td>路由表</td><td>一份配置，列明哪个地址交给哪个组件处理</td></tr><tr><td>动态参数</td><td>地址里会变的部分，比如 <code>/activities/:id</code> 里的 <code>id</code></td></tr><tr><td>查询参数</td><td>地址里 <code>?</code> 后面的键值对，比如 <code>?page=2</code></td></tr><tr><td>守卫</td><td>在跳转发生前后执行的函数，用来做拦截和判断</td></tr><tr><td>凭证</td><td>登录成功后服务端给的 token，之后每次请求都带上它证明身份</td></tr></tbody></table><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>先读 <a href="/frontend-engineering-course/unit09/01-router-basics.html">9.1 路由基础</a>，把“地址 ↔ 组件”的对应关系建起来。 然后按顺序读到 9.4，<a href="/frontend-engineering-course/unit09/05-case-auth.html">案例 10</a> 是这一周的课堂演练。 做完案例，你就有了进入第 10 周的基础。</p>',26))])}const f=d(l,[["render",s]]);export{m as __pageData,f as default};
